SIDES = ("right", "left")


# ----------------------------------------------------------------------------------------------------------
# Batch forward kinematics of one arm, in the openarm_body_link0 frame
# ----------------------------------------------------------------------------------------------------------
def _quat2mat(model, q):
    R = np.zeros(9)
    mujoco.mju_quat2Mat(R, np.asarray(q, float))
    return R.reshape(3, 3)


def arm_chain(model, side):
    """Static transforms and hinge axes from openarm_body_link0 down to the TCP, read from the model."""
    out = []
    for n in ("link0", "link1", "link2", "link3", "link4", "link5", "link6", "link7", "link8", "hand", "hand_tcp"):
        b = model.body(f"openarm_{side}_{n}")
        axis = None
        if b.jntnum[0] > 0:
            jid = int(b.jntadr[0])
            assert model.jnt_type[jid] == mujoco.mjtJoint.mjJNT_HINGE and np.allclose(model.jnt_pos[jid], 0)
            axis = model.jnt_axis[jid].copy()
        out.append((model.body_pos[b.id].copy(), _quat2mat(model, model.body_quat[b.id]), axis))
    return out


def batch_fk(chain, Q):
    """Q (N, 7) -> TCP position (N, 3) and rotation (N, 3, 3) in the body_link0 frame."""
    N = len(Q)
    R = np.tile(np.eye(3), (N, 1, 1))
    p = np.zeros((N, 3))
    k = 0
    for pos, Rs, ax in chain:
        p = p + np.einsum("nij,j->ni", R, pos)
        R = R @ Rs
        if ax is not None:
            q = Q[:, k]
            k += 1
            K = np.array([[0, -ax[2], ax[1]], [ax[2], 0, -ax[0]], [-ax[1], ax[0], 0]])
            c, s = np.cos(q)[:, None, None], np.sin(q)[:, None, None]
            R = R @ (c * np.eye(3) + s * K + (1 - c) * np.outer(ax, ax))
    return p, R


def usable_samples(model, side, rng):
    """Sample joint space; return (TCP positions, joint vectors) of the samples with a usable gripper pose.

    Cached in OUT_DIR keyed by the sampling settings, because the samples do not depend on the poses."""
    chain = arm_chain(model, side)
    jnt = arm_ids(model, side)["jnt"]
    lo, hi = model.jnt_range[jnt, 0], model.jnt_range[jnt, 1]
    key = "_".join(str(C[k]) for k in ("n_samples", "seed", "approach_down_deg", "approach_cone_deg", "finger_axis_max_z"))
    cache = OUT_DIR / f"samples_{side}_{key}.npz"
    if cache.exists():
        z = np.load(cache)
        return z["P"], z["Q"], lo, hi
    a_nom = np.array([math.cos(math.radians(C["approach_down_deg"])), 0.0, -math.sin(math.radians(C["approach_down_deg"]))])
    cos_cone = math.cos(math.radians(C["approach_cone_deg"]))
    P, Qs, n_done, chunk = [], [], 0, 250_000
    while n_done < C["n_samples"]:
        Q = rng.uniform(lo, hi, (chunk, 7))
        p, R = batch_fk(chain, Q)
        keep = (R[:, :, 2] @ a_nom >= cos_cone) & (np.abs(R[:, 2, 1]) <= C["finger_axis_max_z"])
        P.append(p[keep])
        Qs.append(Q[keep])
        n_done += chunk
    P, Qs = np.concatenate(P), np.concatenate(Qs)
    np.savez_compressed(cache, P=P, Q=Qs)
    return P, Qs, lo, hi


# ----------------------------------------------------------------------------------------------------------
# Geometry: footprint against the bench
# ----------------------------------------------------------------------------------------------------------
def base_footprint(model, data):
    """(xmin, xmax, ymin, ymax) of base_link's mesh in its own frame."""
    g = model.geom("base_link_geom")
    mid = g.dataid[0]
    V = model.mesh_vert[model.mesh_vertadr[mid]:model.mesh_vertadr[mid] + model.mesh_vertnum[mid]]
    W = (data.geom_xmat[g.id].reshape(3, 3) @ V.T).T + data.geom_xpos[g.id]
    b = model.body("base_link").id
    L = (data.xmat[b].reshape(3, 3).T @ (W - data.xpos[b]).T).T
    return float(L[:, 0].min()), float(L[:, 0].max()), float(L[:, 1].min()), float(L[:, 1].max())


def footprint_points(fp, xy, yaw, n=40):
    x0, x1, y0, y1 = fp
    xs, ys = np.linspace(x0, x1, n), np.linspace(y0, y1, n)
    pts = np.concatenate([np.c_[xs, np.full(n, y0)], np.c_[xs, np.full(n, y1)],
                          np.c_[np.full(n, x0), ys], np.c_[np.full(n, x1), ys]])
    R = np.array([[math.cos(yaw), -math.sin(yaw)], [math.sin(yaw), math.cos(yaw)]])
    return pts @ R.T + np.asarray(xy)


def rect_clearance(pts, half_x, half_y):
    """Smallest distance from points to an axis-aligned rectangle centred on the origin (negative if inside)."""
    dx, dy = np.abs(pts[:, 0]) - half_x, np.abs(pts[:, 1]) - half_y
    out = np.hypot(np.maximum(dx, 0), np.maximum(dy, 0))
    inside = (dx < 0) & (dy < 0)
    out[inside] = np.maximum(dx, dy)[inside]
    return float(out.min())


def swept_clearance(fp, xy, yaw0, yaw1, half_x, half_y, n=25):
    """Smallest footprint-to-bench distance while turning in place from yaw0 to yaw1 (the way DRIVE turns)."""
    d = wrap(yaw1 - yaw0)
    return min(rect_clearance(footprint_points(fp, xy, yaw0 + d * t), half_x, half_y) for t in np.linspace(0, 1, n))


def robot_body_ids(model):
    root = model.body("base_link").id
    return {b for b in range(model.nbody) if _is_under(model, b, root)}


def _is_under(model, b, root):
    while b > 0:
        if b == root:
            return True
        b = model.body_parentid[b]
    return False


def furniture_clearance(model, data, robot_bodies, base_geoms, dist_max=0.4):
    """Smallest distance between the base geoms and every non-robot geom that collides (mj_geomDistance)."""
    best = dist_max
    fromto = np.zeros(6)
    for g in range(model.ngeom):
        if model.geom_bodyid[g] in robot_bodies or (model.geom_contype[g] == 0 and model.geom_conaffinity[g] == 0):
            continue
        if model.geom_bodyid[g] == 0:         # the floor plane
            continue
        for bg in base_geoms:
            best = min(best, mujoco.mj_geomDistance(model, data, bg, g, dist_max, fromto))
    return best


# ----------------------------------------------------------------------------------------------------------
# Eagle camera visibility
# ----------------------------------------------------------------------------------------------------------
def visibility(model, data, cam_id, geom_sets, fovy_deg, aspect, nx=64, ny=48):
    """Fraction of the camera image covered by each geom set, from a nx x ny grid of rays (first hit counts, so
    occlusion by the bench edge or the arms is included). geom_sets: {name: set of geom ids}."""
    pos, R = data.cam_xpos[cam_id].copy(), data.cam_xmat[cam_id].reshape(3, 3)
    th = math.tan(math.radians(fovy_deg) / 2)
    u, v = np.meshgrid(np.linspace(-1, 1, nx), np.linspace(-1, 1, ny))
    dirs_c = np.c_[(u * th * aspect).ravel(), (v * th).ravel(), -np.ones(nx * ny)]
    dirs = (R @ (dirs_c / np.linalg.norm(dirs_c, axis=1, keepdims=True)).T).T
    geomid = np.zeros(nx * ny, dtype=np.int32)
    dist = np.zeros(nx * ny)
    mujoco.mj_multiRay(model, data, pos, dirs.ravel(), None, 1, -1, geomid, dist, None, nx * ny, 1e10)
    return {k: float(np.isin(geomid, list(ids)).mean()) for k, ids in geom_sets.items()}


# ----------------------------------------------------------------------------------------------------------
# IK on the batch FK (position hard, gripper pose soft), in the body_link0 frame
# ----------------------------------------------------------------------------------------------------------
def ik_refine(chain, q0, lo, hi, p_t, a_des, w_a=1.0, w_y=1.0, iters=80, lam=0.02):
    """Position is the goal; the gripper limits only push back once the pose is within 20% of leaving the allowed set."""
    q = np.clip(q0.copy(), lo, hi)
    ang_soft = 0.8 * math.radians(C["approach_cone_deg"])
    y_soft = 0.8 * C["finger_axis_max_z"]

    def resid(Q):
        p, R = batch_fk(chain, Q)
        ang = np.arccos(np.clip(R[:, :, 2] @ a_des, -1, 1))
        return np.c_[p - p_t, w_a * np.maximum(0.0, ang - ang_soft), w_y * np.maximum(0.0, np.abs(R[:, 2, 1]) - y_soft)]

    for _ in range(iters):
        r = resid(q[None])[0]
        eps = 1e-6
        Qp = np.tile(q, (7, 1))
        Qp[np.arange(7), np.arange(7)] += eps
        J = ((resid(Qp) - r) / eps).T                           # (5 residuals, 7 joints)
        dq = -J.T @ np.linalg.solve(J @ J.T + lam ** 2 * np.eye(5), r)
        n = np.abs(dq).max()
        q = np.clip(q + dq * (min(1.0, 0.3 / n) if n > 0 else 1.0), lo, hi)
        if np.linalg.norm(r) < 1e-6:
            break
    p, R = batch_fk(chain, q[None])
    return q, p[0], R[0]


def ik_best(chain, tree, Qs, lo, hi, p_t, a_des, k=150):
    """IK from the k nearest usable samples; returns the best solution that meets the gripper limits, or None."""
    _, idx = tree.query(p_t, k=k)
    cos_cone = math.cos(math.radians(C["approach_cone_deg"]))
    best = None
    for i in np.atleast_1d(idx):
        q, p, R = ik_refine(chain, Qs[i], lo, hi, p_t, a_des)
        perr = float(np.linalg.norm(p - p_t))
        ang = math.acos(float(np.clip(R[:, 2] @ a_des, -1, 1)))
        ok = perr < 0.002 and R[:, 2] @ a_des >= cos_cone and abs(R[2, 1]) <= C["finger_axis_max_z"]
        margin = float(np.min(np.minimum(q - lo, hi - q) / (hi - lo)))
        cost = ang + max(0.0, 0.12 - margin) * 5.0 + 0.4 * float(np.linalg.norm(q))   # stay clear of the limits and near the resting pose
        cand = (not ok, perr if not ok else cost, q, perr, ang, margin)
        if best is None or cand[:2] < best[:2]:
            best = cand
    ok, _, q, perr, ang, margin = best
    return dict(ok=not ok, q=q, pos_err=perr, approach_err_deg=math.degrees(ang), joint_margin=margin)


# ----------------------------------------------------------------------------------------------------------
# Arm path from the hanging pose to the ready pose
# ----------------------------------------------------------------------------------------------------------
def plan_arm_path(model, data, side, base_xy, yaw, z_rest, pedestal_q, rest_q, ready_q, margin, tries=6000, seed=0):
    """One waypoint such that rest -> via -> ready (straight lines in joint space) stays `margin` clear of everything
    that is not the robot (bench, hotplate, beaker, furniture) with no self-collision; the shortest of the sampled ones.

    A straight joint-space move from the hanging pose swings the hand through the bench top (measured: 4.6 cm of
    penetration half way), so the arm first has to lift up and out. Returns (via, direct_ok, via_length, direct_length).
    """
    ids = arm_ids(model, side)
    data.qpos[0:7] = [base_xy[0], base_xy[1], z_rest, *yaw_to_quat(yaw)]
    for jn in robot_specs.PEDESTAL_SPECS["joints"]:
        data.qpos[model.joint(jn).qposadr[0]] = pedestal_q
    for a in ids["fingers"]:
        data.qpos[model.jnt_qposadr[model.actuator_trnid[a, 0]]] = C["finger_open"]
    root = model.body("base_link").id
    under = lambda b: _is_under(model, b, root)
    arm_bodies = {b for b in range(model.nbody) if model.body(b).name.startswith(f"openarm_{side}_")}
    moving = {b for b in arm_bodies if not model.body(b).name.endswith("link0")}
    arm_g = [g for g in range(model.ngeom) if model.geom_bodyid[g] in moving and model.geom_group[g] == 3]
    other_g = [g for g in range(model.ngeom) if not under(int(model.geom_bodyid[g])) and model.geom_bodyid[g] != 0
               and (model.geom_contype[g] or model.geom_conaffinity[g])]
    fromto = np.zeros(6)

    def ok(q):
        for k, a in enumerate(ids["qadr"]):
            data.qpos[a] = q[k]
        mujoco.mj_forward(model, data)
        for i in range(data.ncon):                                   # self-collision of the arm with the robot (excluded pairs never appear)
            c = data.contact[i]
            b1, b2 = int(model.geom_bodyid[c.geom1]), int(model.geom_bodyid[c.geom2])
            if c.dist < 0 and under(b1) and under(b2) and (b1 in moving or b2 in moving) and 0 not in (b1, b2):
                return False
        for g in arm_g:
            for o in other_g:
                if mujoco.mj_geomDistance(model, data, g, o, margin, fromto) < margin:
                    return False
        return True

    seg_ok = lambda a, b, n=25: all(ok(a + t * (b - a)) for t in np.linspace(0, 1, n))
    rest_q, ready_q = np.asarray(rest_q, float), np.asarray(ready_q, float)
    direct_len = float(np.linalg.norm(ready_q - rest_q))
    if seg_ok(rest_q, ready_q):
        return None, True, direct_len, direct_len
    rng = np.random.default_rng(seed)
    lo, hi = model.jnt_range[ids["jnt"], 0], model.jnt_range[ids["jnt"], 1]
    mid, best = 0.5 * (rest_q + ready_q), None
    for _ in range(tries):
        v = np.clip(mid + rng.normal(0, 0.9, 7), lo, hi)
        length = float(np.linalg.norm(v - rest_q) + np.linalg.norm(ready_q - v))
        if (best is None or length < best[0]) and ok(v) and seg_ok(rest_q, v) and seg_ok(v, ready_q):
            best = (length, v)
    return (best[1], False, best[0], direct_len) if best else (None, False, None, direct_len)


# ----------------------------------------------------------------------------------------------------------
def main():
    t_start = time.time()
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    sim = load_task()
    model, data = sim.model, sim.data
    spawn_and_settle(sim)                                      # reads the resting base height; arms hang at zero
    z_rest = float(data.qpos[2])
    top = bench_top_z(model)
    bg = model.geom("bench_top")
    bench_hx, bench_hy = float(model.geom_size[bg.id][0]), float(model.geom_size[bg.id][1])
    bench_cx, bench_cy = float(model.geom_pos[bg.id][0]), float(model.geom_pos[bg.id][1])
    assert abs(bench_cx) < 1e-9 and abs(bench_cy) < 1e-9, "rect_clearance assumes the bench top is centred on the origin"
    fp = base_footprint(model, data)
    yaw_f = TASK_CFG["staging_yaw"]
    assert abs(yaw_f + math.pi / 2) < 1e-9, "the grid places the base on the +y side of the bench, facing -y"
    fwd = np.array([math.cos(yaw_f), math.sin(yaw_f)])        # robot forward in the world at the staging yaw
    mujoco.mj_forward(model, data)

    # ---- object geometry from the model
    beaker_h = 2 * float(model.geom_size[model.geom("task_beaker_glass").id][1])   # cylinder size = (radius, half height)
    beaker_r = float(model.geom_size[model.geom("task_beaker_glass").id][0])
    plate_top_z = top + float(model.site_pos[model.site("hotplate_top").id][2])
    bxy, hxy = np.array(TASK_CFG["beaker_xy"]), np.array(TASK_CFG["hotplate_xy"])
    targets = {
        "grasp": np.r_[bxy, top + C["grasp_height_frac"] * beaker_h],
        "place": np.r_[hxy, plate_top_z + C["place_clear_above_plate"]],
        "ready": np.r_[bxy - C["ready_back_off"] * fwd, top + beaker_h + C["ready_clear_above_top"]],
    }
    print(f"base resting z {z_rest:.4f} m; footprint x[{fp[0]:.3f},{fp[1]:.3f}] y[{fp[2]:.3f},{fp[3]:.3f}]; bench top z {top:.3f}, "
          f"beaker {2 * beaker_r * 1000:.0f} mm x {beaker_h * 1000:.0f} mm; hotplate_top z {plate_top_z:.3f}")
    for k, v in targets.items():
        print(f"  target {k:5s} {v.round(3)}")

    # ---- 1. reachable TCP samples
    rng = np.random.default_rng(C["seed"])
    samples = {}
    for side in SIDES:
        t0 = time.time()
        P, Qs, lo, hi = usable_samples(model, side, rng)
        samples[side] = dict(P=P, Q=Qs, lo=lo, hi=hi, tree=cKDTree(P), chain=arm_chain(model, side))
        print(f"{side} arm: {C['n_samples']:,} joint samples -> {len(P):,} usable gripper poses ({time.time() - t0:.0f} s)")

    # ---- 2./3. candidate grid
    rot = lambda yaw: np.array([[math.cos(yaw), -math.sin(yaw)], [math.sin(yaw), math.cos(yaw)]])
    mid_x = 0.5 * (bxy[0] + hxy[0])
    bench_edge_y = bench_cy + bench_hy
    spawn_xy = np.array(TASK_CFG["spawn_xy"])
    lowest = robot_specs.PEDESTAL_SPECS["lowest_command"]
    pedestal_qs = [q for q in C["pedestal_qs"] if q >= lowest + C["pedestal_stop_margin"]]
    print(f"pedestal commands searched: {pedestal_qs} (the lowest command {lowest} is the torso-contact stop)")
    rows = []
    for st in C["standoffs"]:
        y_c = bench_edge_y + st + fp[1]                        # facing -y: the base front (x = fp[1]) is st from the bench edge
        for lat in C["laterals"]:
            xy = np.array([mid_x + lat, y_c])
            clear = rect_clearance(footprint_points(fp, xy, yaw_f), bench_hx, bench_hy)
            heading = math.atan2(*(xy - spawn_xy)[::-1])
            swept = swept_clearance(fp, xy, heading, yaw_f, bench_hx, bench_hy)
            for q in pedestal_qs:
                body_z = z_rest + 0.75 + 2 * q
                for side in SIDES:
                    s = samples[side]
                    g, cnt = {}, {}
                    for name, tw in targets.items():
                        tb = np.r_[rot(yaw_f).T @ (tw[:2] - xy), tw[2] - body_z]
                        g[name] = float(s["tree"].query(tb)[0])
                        cnt[name] = int(s["tree"].query_ball_point(tb, C["reach_radius"], return_length=True))
                    rows.append(dict(standoff=st, lateral=lat, x=xy[0], y=xy[1], pedestal_q=q, arm=side, clearance=clear,
                                     swept_clearance=swept, gap_grasp=g["grasp"], gap_place=g["place"], gap_ready=g["ready"],
                                     worst_gap=max(g.values()), reach_count=min(cnt.values()), visible=-1))
    print(f"{len(rows)} candidates ({len(C['standoffs'])} standoffs x {len(C['laterals'])} laterals x "
          f"{len(pedestal_qs)} heights x 2 arms)")
    ok_rows = [r for r in rows if r["clearance"] >= C["min_clearance"] and r["swept_clearance"] >= C["min_turn_clearance"]]
    print(f"{len(ok_rows)} keep the footprint >= {C['min_clearance'] * 100:.0f} cm from the bench and the final turn >= "
          f"{C['min_turn_clearance'] * 100:.0f} cm")

    # furniture check on the footprint candidates that survive (base only, arms at rest, yaw = staging yaw and the approach heading)
    robot_bodies = robot_body_ids(model)
    base_geoms = [g for g in range(model.ngeom) if model.geom_bodyid[g] == model.body("base_link").id]
    free_dof = model.jnt_qposadr[0]
    furn_cache = {}

    def furniture(xy, yaw):
        key = (round(xy[0], 3), round(xy[1], 3), round(yaw, 3))
        if key not in furn_cache:
            data.qpos[free_dof:free_dof + 7] = [xy[0], xy[1], z_rest, *yaw_to_quat(yaw)]
            mujoco.mj_kinematics(model, data)
            mujoco.mj_comPos(model, data)
            furn_cache[key] = furniture_clearance(model, data, robot_bodies, base_geoms)
        return furn_cache[key]

    ok2 = []
    for r in ok_rows:
        xy = np.array([r["x"], r["y"]])
        heading = math.atan2(*(xy - spawn_xy)[::-1])
        r["furniture"] = min(furniture(xy, yaw_f), furniture(xy, heading))
        if r["furniture"] >= 0.03:
            ok2.append(r)
    print(f"{len(ok2)} also keep >= 3 cm from other furniture at the staging yaw and at the approach heading")

    # ---- 4. rank: gap (to the sample resolution), then eagle camera visibility, then reach depth, then standoff
    best_gap = min(r["worst_gap"] for r in ok2)
    res = C["gap_resolution"]
    tied = [r for r in ok2 if r["worst_gap"] <= best_gap + res]
    print(f"best worst-case gap {best_gap * 1000:.1f} mm; {len(tied)} candidates within {res * 1000:.0f} mm of it")

    cam = model.camera("eagle_cam")
    spec = robot_specs.CAMERA_SPECS[0]
    aspect = spec["resolution"][0] / spec["resolution"][1]
    geom_sets = {"beaker": {model.geom("task_beaker_glass").id},
                 "hotplate": {model.geom("task_hotplate_top_plate").id}}      # the top plate: that is the surface the task is about
    for r in tied:
        data.qpos[free_dof:free_dof + 7] = [r["x"], r["y"], z_rest, *yaw_to_quat(yaw_f)]
        for jn in robot_specs.PEDESTAL_SPECS["joints"]:
            data.qpos[model.joint(jn).qposadr[0]] = r["pedestal_q"]
        mujoco.mj_forward(model, data)
        fr = visibility(model, data, cam.id, geom_sets, spec["fovy"], aspect)
        r["visible_beaker"], r["visible_plate"] = fr["beaker"], fr["hotplate"]
        r["visible"] = min(fr["beaker"], fr["hotplate"])             # the less visible of the two objects
        r["eagle_z"] = float(data.cam_xpos[cam.id][2])
    tied.sort(key=lambda r: (-round(r["visible"], 3), -r["reach_count"], -r["standoff"]))
    print(f"eagle camera: {spec['resolution'][0]}x{spec['resolution'][1]}, fovy {spec['fovy']} deg, level, fixed to the torso")
    print("top candidates (eagle = share of the eagle image covered by beaker / hotplate; ranked on the smaller):")
    for r in tied[:8]:
        print(f"  {r['arm']:5s} standoff {r['standoff']:.2f} lat {r['lateral']:+.2f} q {r['pedestal_q']:+.3f}  "
              f"gaps g/p/r {r['gap_grasp'] * 1000:.1f}/{r['gap_place'] * 1000:.1f}/{r['gap_ready'] * 1000:.1f} mm  "
              f"reach_count {r['reach_count']:5d}  eagle {100 * r['visible_beaker']:.1f}%/{100 * r['visible_plate']:.1f}%  eagle z {r['eagle_z']:.2f}  "
              f"clear {r['clearance'] * 100:.1f} cm swept {r['swept_clearance'] * 100:.1f} cm furn {r['furniture'] * 100:.0f} cm")

    print("best sampled candidate per pedestal command (screening only; eagle = image share of beaker / hotplate top plate):")
    for q in pedestal_qs:
        pool = [r for r in ok2 if r["pedestal_q"] == q]
        if not pool:
            continue
        b = min(pool, key=lambda r: r["worst_gap"])
        data.qpos[free_dof:free_dof + 7] = [b["x"], b["y"], z_rest, *yaw_to_quat(yaw_f)]
        for jn in robot_specs.PEDESTAL_SPECS["joints"]:
            data.qpos[model.joint(jn).qposadr[0]] = q
        mujoco.mj_forward(model, data)
        fr = visibility(model, data, cam.id, geom_sets, spec["fovy"], aspect)
        print(f"  q {q:+.3f}: {b['arm']:5s} lat {b['lateral']:+.2f} standoff {b['standoff']:.2f} worst gap {b['worst_gap'] * 1000:5.1f} mm  "
              f"eagle z {data.cam_xpos[cam.id][2]:.2f}  eagle {100 * fr['beaker']:.1f}% / {100 * fr['hotplate']:.1f}%")

    with open(OUT_DIR / "candidates.csv", "w", newline="") as f:
        keys = sorted({k for r in rows for k in r})
        w = csv.DictWriter(f, fieldnames=keys)
        w.writeheader()
        w.writerows(rows)

    # ---- 5. IK refine the winners until one has a collision-free ready pose
    result = None
    for r in tied[:60]:
        side = r["arm"]
        s = samples[side]
        xy = np.array([r["x"], r["y"]])
        R2 = rot(yaw_f)
        body_z = z_rest + 0.75 + 2 * r["pedestal_q"]
        a_des_w = np.r_[fwd * math.cos(math.radians(C["approach_down_deg"])), -math.sin(math.radians(C["approach_down_deg"]))]
        a_des = np.r_[R2.T @ a_des_w[:2], a_des_w[2]]
        ik = {}
        for name, tw in targets.items():
            tb = np.r_[R2.T @ (tw[:2] - xy), tw[2] - body_z]
            ik[name] = ik_best(s["chain"], s["tree"], s["Q"], s["lo"], s["hi"], tb, a_des)
        # ready pose in MuJoCo: place everything, check contacts
        ids = arm_ids(model, side)
        data.qpos[free_dof:free_dof + 7] = [r["x"], r["y"], z_rest, *yaw_to_quat(yaw_f)]
        for jn in robot_specs.PEDESTAL_SPECS["joints"]:
            data.qpos[model.joint(jn).qposadr[0]] = r["pedestal_q"]
        for k, qa in enumerate(ik["ready"]["q"]):
            data.qpos[ids["qadr"][k]] = qa
        for a in ids["fingers"]:
            data.qpos[model.jnt_qposadr[model.actuator_trnid[a, 0]]] = C["finger_open"]
        mujoco.mj_forward(model, data)
        tcp = data.body(f"openarm_{side}_hand_tcp").xpos.copy()
        arm_bodies = {b for b in range(model.nbody) if model.body(b).name.startswith(f"openarm_{side}_")}
        contacts = []                       # the chosen arm against anything but the floor (the idle arm's closed fingers overlap 3.5 mm)
        for i in range(data.ncon):
            c = data.contact[i]
            b1, b2 = model.geom_bodyid[c.geom1], model.geom_bodyid[c.geom2]
            if 0 in (b1, b2) or not ({b1, b2} & arm_bodies) or c.dist > 0:
                continue
            contacts.append((model.geom(c.geom1).name, model.geom(c.geom2).name, round(float(c.dist), 4)))
        mj_err = float(np.linalg.norm(tcp - targets["ready"]))
        print(f"IK {side} lat {r['lateral']:+.2f} q {r['pedestal_q']:+.3f}: " + "; ".join(
            f"{n} {v['pos_err'] * 1000:.2f} mm {'ok' if v['ok'] else 'GRIPPER LIMITS NOT MET'} (approach {v['approach_err_deg']:.0f} deg, "
            f"joint margin {v['joint_margin']:.2f})" for n, v in ik.items()) +
              f"; MuJoCo TCP error {mj_err * 1000:.2f} mm; contacts {contacts if contacts else 'none'}")
        if all(v["ok"] for v in ik.values()) and not contacts and mj_err < 0.002:
            result = dict(candidate=r, ik=ik, tcp=tcp, contacts=contacts)
            break
    if result is None:
        print("NO candidate with a collision-free, IK-verified ready pose")
        return

    r, ik = result["candidate"], result["ik"]
    t0 = time.time()
    via, direct_ok, via_len, direct_len = plan_arm_path(
        model, data, r["arm"], (r["x"], r["y"]), yaw_f, z_rest, r["pedestal_q"], np.zeros(7), ik["ready"]["q"], C["path_margin"])
    print(f"arm path: direct joint-space move {'is clear' if direct_ok else 'hits the bench or objects'} (length {direct_len:.2f} rad); "
          + ("no waypoint needed" if direct_ok else f"waypoint found, path length {via_len:.2f} rad" if via is not None else "NO WAYPOINT FOUND")
          + f" ({time.time() - t0:.0f} s)")
    if via is None and not direct_ok:
        return
    gaps = {"grasp": ik["grasp"]["pos_err"], "place": ik["place"]["pos_err"], "ready": ik["ready"]["pos_err"]}
    summary = dict(
        arm=r["arm"], staging_xy=[r["x"], r["y"]], staging_yaw=yaw_f, pedestal_q=r["pedestal_q"],
        ready_q=[float(v) for v in ik["ready"]["q"]], ready_via_q=None if via is None else [float(v) for v in via],
        path_length=via_len, direct_path_length=direct_len, ready_tcp=[float(v) for v in result["tcp"]],
        standoff=r["standoff"], lateral=r["lateral"], clearance=r["clearance"], swept_clearance=r["swept_clearance"],
        furniture_clearance=r["furniture"], base_resting_z=z_rest,
        sample_gaps={"grasp": r["gap_grasp"], "place": r["gap_place"], "ready": r["gap_ready"]},
        ik_gaps=gaps, eagle_image_share={"beaker": r["visible_beaker"], "hotplate": r["visible_plate"]}, eagle_z=r["eagle_z"],
        targets={k: [float(x) for x in v] for k, v in targets.items()},
        ik_details={k: {kk: (vv.tolist() if isinstance(vv, np.ndarray) else vv) for kk, vv in v.items()} for k, v in ik.items()},
        flagged=[k for k, v in {**{f"sample_{k}": v for k, v in
                                   {"grasp": r["gap_grasp"], "place": r["gap_place"], "ready": r["gap_ready"]}.items()},
                                **{f"ik_{k}": v for k, v in gaps.items()}}.items() if v > C["gap_flag"]],
        search_seconds=time.time() - t_start)
    (OUT_DIR / "staging_result.json").write_text(json.dumps(summary, indent=2))

    print("\n=== chosen staging pose ===")
    print(f"arm {r['arm']}; staging xy ({r['x']:.3f}, {r['y']:.3f}) yaw {math.degrees(yaw_f):.0f} deg; pedestal_q {r['pedestal_q']:+.3f} "
          f"(shoulder-line z {z_rest + 0.75 + 2 * r['pedestal_q'] + 0.698:.3f} m); standoff {r['standoff'] * 100:.0f} cm")
    print(f"footprint clearance {r['clearance'] * 100:.1f} cm; turn-swept {r['swept_clearance'] * 100:.1f} cm; furniture {r['furniture'] * 100:.0f} cm")
    for k in targets:
        print(f"gap {k:5s}: sampled {summary['sample_gaps'][k] * 1000:6.1f} mm   IK {gaps[k] * 1000:6.2f} mm")
    print("flagged (> 3 cm):", summary["flagged"] or "none")
    print("\nPaste into src/task_config.py TASK_CFG:")
    print(f'    "staging_xy": ({r["x"]:.4f}, {r["y"]:.4f}),\n    "pedestal_q": {r["pedestal_q"]},\n    "arm": "{r["arm"]}",\n'
          f'    "ready_q": ({", ".join(f"{v:.5f}" for v in ik["ready"]["q"])}),\n'
          f'    "ready_tcp": ({", ".join(f"{v:.4f}" for v in result["tcp"])}),\n'
          f'    "ready_via_q": {None if via is None else "(" + ", ".join(f"{v:.5f}" for v in via) + ")"},')


if __name__ == "__main__":
    main()
